from bisect import bisect_left

def longest_rising(nums: list[int]) -> int:
    tails = []                           # tails[k]: smallest value that ends a rising subsequence of length k + 1
    for x in nums:
        k = bisect_left(tails, x)        # the first end that is not below x
        if k == len(tails):
            tails.append(x)              # x extends the longest subsequence
        else:
            tails[k] = x                 # a smaller end for length k + 1
    return len(tails)

perf.naive:
def longest_rising(nums: list[int]) -> int:
    best = [1] * len(nums)               # best[i]: longest rising subsequence ending at i, from every earlier index
    for i in range(len(nums)):
        for j in range(i):
            if nums[j] < nums[i] and best[j] + 1 > best[i]:
                best[i] = best[j] + 1
    return max(best, default=0)
